solution.javascript:
function orangesRotting(grid) {
  const m = grid.length, n = grid[0].length;
  let fresh = 0, q = [];
  for (let r=0;r<m;r++) for (let c=0;c<n;c++) {
    if (grid[r][c]===1) fresh++;
    if (grid[r][c]===2) q.push([r,c]);
  }
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  let mins = 0;
  while (q.length && fresh > 0) {
    const next = [];
    for (const [r,c] of q) {
      for (const [dr,dc] of dirs) {
        const nr = r+dr, nc = c+dc;
        if (nr>=0&&nr<m&&nc>=0&&nc<n&&grid[nr][nc]===1) { grid[nr][nc]=2; fresh--; next.push([nr,nc]); }
      }
    }
    q = next; if (q.length) mins++;
  }
  return fresh > 0 ? -1 : mins;
}

solution.cpp:
int orangesRotting(vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size(), fresh = 0;
    queue<pair<int,int>> q;
    for (int r=0;r<m;r++) for (int c=0;c<n;c++) {
        if (grid[r][c]==1) fresh++;
        if (grid[r][c]==2) q.push({r,c});
    }
    int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}}, mins = 0;
    while (!q.empty() && fresh) {
        int sz = q.size();
        while (sz--) {
            auto [r,c] = q.front(); q.pop();
            for (int d=0;d<4;d++) {
                int nr = r+dirs[d][0], nc = c+dirs[d][1];
                if (nr>=0&&nr<m&&nc>=0&&nc<n&&grid[nr][nc]==1) { grid[nr][nc]=2; fresh--; q.push({nr,nc}); }
            }
        }
        if (!q.empty()) mins++;
    }
    return fresh ? -1 : mins;
}
